-- name: GetMembershipOffboardingByIdempotency :one
SELECT id,tenant_id,target_membership_id,successor_membership_id,actor_id,state,version,reason,assignment_generation,workspace_count,requirement_count,review_count,started_at,tenant_transferred_at,completed_at,cancelled_at,request_hash FROM tenancy.membership_offboarding_operations WHERE actor_id=sqlc.arg(actor_id) AND key_hash=sqlc.arg(key_hash);
-- name: LockMembershipOffboardingParties :one
SELECT target.user_id AS target_user_id,successor.user_id AS successor_user_id,t.assignment_generation,
 (SELECT count(*)::bigint FROM tenancy.memberships m JOIN identity.users u ON u.id=m.user_id WHERE m.tenant_id=t.id AND m.id<>target.id AND m.state='ACTIVE' AND u.email_verified_at IS NOT NULL AND u.disabled_at IS NULL AND EXISTS(SELECT 1 FROM tenancy.role_grants a WHERE a.membership_id=m.id AND a.capability='tenant.memberships.manage' AND a.effect='ALLOW' AND a.revoked_at IS NULL) AND NOT EXISTS(SELECT 1 FROM tenancy.role_grants d WHERE d.membership_id=m.id AND d.capability='tenant.memberships.manage' AND d.effect='DENY' AND d.revoked_at IS NULL)) AS other_admin_count
FROM bidora_tenancy.tenants t JOIN tenancy.memberships actor ON actor.tenant_id=t.id JOIN identity.users actor_user ON actor_user.id=actor.user_id JOIN tenancy.memberships target ON target.id=sqlc.arg(target_membership_id) AND target.tenant_id=t.id JOIN tenancy.memberships successor ON successor.id=sqlc.arg(successor_membership_id) AND successor.tenant_id=t.id JOIN identity.users successor_user ON successor_user.id=successor.user_id
WHERE t.id=sqlc.arg(tenant_id) AND t.state='ACTIVE' AND t.tenant_type='TENDERPRENEUR' AND actor.user_id=sqlc.arg(actor_id) AND actor.state='ACTIVE' AND actor.context_generation=sqlc.arg(actor_generation) AND actor_user.email_verified_at IS NOT NULL AND actor_user.disabled_at IS NULL AND target.state='ACTIVE' AND target.context_generation=sqlc.arg(target_generation) AND successor.id<>target.id AND successor.state='ACTIVE' AND successor_user.email_verified_at IS NOT NULL AND successor_user.disabled_at IS NULL
AND EXISTS(SELECT 1 FROM tenancy.role_grants a WHERE a.membership_id=actor.id AND a.capability='tenant.memberships.manage' AND a.effect='ALLOW' AND a.revoked_at IS NULL) AND NOT EXISTS(SELECT 1 FROM tenancy.role_grants d WHERE d.membership_id=actor.id AND d.capability='tenant.memberships.manage' AND d.effect='DENY' AND d.revoked_at IS NULL)
AND EXISTS(SELECT 1 FROM tenancy.role_grants a WHERE a.membership_id=successor.id AND a.capability='tenderpreneur.bid.read' AND a.effect='ALLOW' AND a.revoked_at IS NULL) AND NOT EXISTS(SELECT 1 FROM tenancy.role_grants d WHERE d.membership_id=successor.id AND d.capability='tenderpreneur.bid.read' AND d.effect='DENY' AND d.revoked_at IS NULL)
FOR UPDATE OF t,actor,target,successor;
-- name: StartMembershipOffboarding :exec
INSERT INTO tenancy.membership_offboarding_operations(id,tenant_id,target_membership_id,successor_membership_id,actor_id,state,version,reason,assignment_generation,key_hash,request_hash,started_at) VALUES(sqlc.arg(id),sqlc.arg(tenant_id),sqlc.arg(target_membership_id),sqlc.arg(successor_membership_id),sqlc.arg(actor_id),'STARTED',1,sqlc.arg(reason),sqlc.arg(assignment_generation),sqlc.arg(key_hash),sqlc.arg(request_hash),sqlc.arg(started_at));
-- name: SetMembershipOffboardingState :execrows
UPDATE tenancy.memberships SET state='OFFBOARDING',context_generation=context_generation+1,updated_at=sqlc.arg(at) WHERE id=sqlc.arg(id) AND state='ACTIVE' AND context_generation=sqlc.arg(expected_generation);
-- name: GetMembershipOffboardingEventByIdempotency :one
SELECT operation_id,request_hash,event_type FROM tenancy.membership_offboarding_events WHERE actor_id=sqlc.arg(actor_id) AND key_hash=sqlc.arg(key_hash);
-- name: InsertMembershipOffboardingEvent :exec
INSERT INTO tenancy.membership_offboarding_events(id,operation_id,sequence,event_type,actor_id,successor_membership_id,reason,key_hash,request_hash,occurred_at) VALUES(sqlc.arg(id),sqlc.arg(operation_id),sqlc.arg(sequence),sqlc.arg(event_type),sqlc.arg(actor_id),sqlc.arg(successor_membership_id),sqlc.arg(reason),sqlc.arg(key_hash),sqlc.arg(request_hash),sqlc.arg(occurred_at));
-- name: GetMembershipOffboarding :one
SELECT o.id,o.tenant_id,o.target_membership_id,o.successor_membership_id,o.actor_id,o.state,o.version,o.reason,o.assignment_generation,o.workspace_count,o.requirement_count,o.review_count,o.started_at,o.tenant_transferred_at,o.completed_at,o.cancelled_at,target.user_id AS target_user_id,successor.user_id AS successor_user_id FROM tenancy.membership_offboarding_operations o JOIN tenancy.memberships target ON target.id=o.target_membership_id JOIN tenancy.memberships successor ON successor.id=o.successor_membership_id WHERE o.id=sqlc.arg(id);
-- name: MarkMembershipTenantTransferred :execrows
UPDATE tenancy.membership_offboarding_operations SET state='TENANT_TRANSFERRED',version=version+1,workspace_count=sqlc.arg(workspace_count),requirement_count=sqlc.arg(requirement_count),review_count=sqlc.arg(review_count),tenant_transferred_at=sqlc.arg(at) WHERE id=sqlc.arg(id) AND state='STARTED' AND version=sqlc.arg(expected_version);
-- name: LockMembershipOffboardingForFinalize :one
SELECT o.id,o.tenant_id,o.target_membership_id,o.successor_membership_id,o.version,o.reason,target.context_generation AS target_generation
FROM tenancy.membership_offboarding_operations o JOIN bidora_tenancy.tenants t ON t.id=o.tenant_id JOIN tenancy.memberships target ON target.id=o.target_membership_id JOIN tenancy.memberships successor ON successor.id=o.successor_membership_id JOIN identity.users successor_user ON successor_user.id=successor.user_id
WHERE o.id=sqlc.arg(id) AND o.state='TENANT_TRANSFERRED' AND o.version=sqlc.arg(expected_version) AND t.state='ACTIVE' AND target.state='OFFBOARDING' AND successor.state='ACTIVE' AND successor_user.email_verified_at IS NOT NULL AND successor_user.disabled_at IS NULL
AND EXISTS(SELECT 1 FROM tenancy.memberships m JOIN identity.users u ON u.id=m.user_id WHERE m.tenant_id=o.tenant_id AND m.id<>target.id AND m.state='ACTIVE' AND u.email_verified_at IS NOT NULL AND u.disabled_at IS NULL AND EXISTS(SELECT 1 FROM tenancy.role_grants ma WHERE ma.membership_id=m.id AND ma.capability='tenant.memberships.manage' AND ma.effect='ALLOW' AND ma.revoked_at IS NULL) AND NOT EXISTS(SELECT 1 FROM tenancy.role_grants md WHERE md.membership_id=m.id AND md.capability='tenant.memberships.manage' AND md.effect='DENY' AND md.revoked_at IS NULL))
AND EXISTS(SELECT 1 FROM tenancy.role_grants a WHERE a.membership_id=successor.id AND a.capability='tenderpreneur.bid.read' AND a.effect='ALLOW' AND a.revoked_at IS NULL) AND NOT EXISTS(SELECT 1 FROM tenancy.role_grants d WHERE d.membership_id=successor.id AND d.capability='tenderpreneur.bid.read' AND d.effect='DENY' AND d.revoked_at IS NULL) FOR UPDATE OF o,t,target,successor;
-- name: RevokeMembershipOffboardingGrants :exec
UPDATE tenancy.role_grants SET revoked_at=sqlc.arg(at) WHERE membership_id=sqlc.arg(membership_id) AND revoked_at IS NULL;
-- name: FinalizeOffboardedMembership :execrows
UPDATE tenancy.memberships SET state='REVOKED',context_generation=context_generation+1,updated_at=sqlc.arg(at) WHERE id=sqlc.arg(id) AND state='OFFBOARDING';
-- name: CompleteMembershipOffboarding :execrows
UPDATE tenancy.membership_offboarding_operations SET state='COMPLETED',version=version+1,completed_at=sqlc.arg(at) WHERE id=sqlc.arg(id) AND state='TENANT_TRANSFERRED' AND version=sqlc.arg(expected_version);
-- name: LockMembershipOffboardingForCancel :one
SELECT o.id,o.tenant_id,o.target_membership_id,o.successor_membership_id,o.version,target.user_id AS target_user_id FROM tenancy.membership_offboarding_operations o JOIN tenancy.memberships target ON target.id=o.target_membership_id WHERE o.id=sqlc.arg(id) AND o.state IN ('STARTED','TENANT_TRANSFERRED') AND o.version=sqlc.arg(expected_version) AND target.state='OFFBOARDING' FOR UPDATE OF o,target;
-- name: CancelMembershipOffboarding :execrows
UPDATE tenancy.membership_offboarding_operations SET state='CANCELLED',version=version+1,cancelled_at=sqlc.arg(at) WHERE id=sqlc.arg(id) AND state IN ('STARTED','TENANT_TRANSFERRED') AND version=sqlc.arg(expected_version);
-- name: ReactivateOffboardingMembership :execrows
UPDATE tenancy.memberships SET state='ACTIVE',context_generation=context_generation+1,updated_at=sqlc.arg(at) WHERE id=sqlc.arg(id) AND state='OFFBOARDING';
-- name: LockMembershipOffboardingForRetarget :one
SELECT o.id,o.tenant_id,o.target_membership_id,o.successor_membership_id,o.version,target.user_id AS target_user_id FROM tenancy.membership_offboarding_operations o JOIN tenancy.memberships target ON target.id=o.target_membership_id WHERE o.id=sqlc.arg(id) AND o.state='STARTED' AND o.version=sqlc.arg(expected_version) FOR UPDATE OF o;
-- name: ValidateOffboardingSuccessor :one
SELECT successor.id,successor.user_id FROM tenancy.memberships successor JOIN identity.users u ON u.id=successor.user_id WHERE successor.id=sqlc.arg(successor_membership_id) AND successor.tenant_id=sqlc.arg(tenant_id) AND successor.state='ACTIVE' AND successor.id<>sqlc.arg(target_membership_id) AND u.email_verified_at IS NOT NULL AND u.disabled_at IS NULL AND EXISTS(SELECT 1 FROM tenancy.role_grants a WHERE a.membership_id=successor.id AND a.capability='tenderpreneur.bid.read' AND a.effect='ALLOW' AND a.revoked_at IS NULL) AND NOT EXISTS(SELECT 1 FROM tenancy.role_grants d WHERE d.membership_id=successor.id AND d.capability='tenderpreneur.bid.read' AND d.effect='DENY' AND d.revoked_at IS NULL) FOR UPDATE OF successor;
-- name: RetargetMembershipOffboarding :execrows
UPDATE tenancy.membership_offboarding_operations SET successor_membership_id=sqlc.arg(successor_membership_id),version=version+1,reason=sqlc.arg(reason) WHERE id=sqlc.arg(id) AND state='STARTED' AND version=sqlc.arg(expected_version);
